/**
 * Pre-baked JPL HORIZONS vectors — the app's JPL-grade ephemeris, offline.
 *
 * `horizonsBakedData.ts` (generated by tools/prep_ephemeris.py) carries Sun (10)
 * and Earth (399) position vectors as seen from the Moon's centre
 * (CENTER 500@301) in the ICRF frame — the exact query `horizonsVectorUrl()`
 * builds — on a uniform 6 h UTC grid across the mission window. They are baked
 * because ssd.jpl.nasa.gov sends no CORS header: a browser can never fetch
 * HORIZONS live, so the deployed static app ships the vectors instead of
 * labelling its ephemeris "fallback".
 *
 * Interpolation is Catmull-Rom; the window's first/last interval uses
 * quadratic-extrapolated ghost knots (p(-h) = 3p0 − 3p1 + p2) so the edges sit
 * on the same accuracy curve as the interior. The bake measured this exact
 * scheme's error at every grid midpoint against exact HORIZONS vectors fetched
 * at those epochs — the numbers live in `HORIZONS_BAKED.validation`.
 */

import { AU_KM, R_EARTH } from "./constants";
import { eqjToMe, skyState, type SkyState } from "./ephemeris";
import { RAD2DEG, type Vec3 } from "./frames";

/** One exact HORIZONS vector probe (grid midpoint) used to measure bake accuracy. */
export interface HorizonsProbeSample {
  epochIso: string;
  sun: [number, number, number];
  earth: [number, number, number];
}

/** Shape of the generated `horizonsBakedData.ts` payload. */
export interface HorizonsBakedFile {
  schema: number;
  generator: string;
  /** HORIZONS endpoint the vectors were fetched from. */
  api: string;
  /** HORIZONS center identifier (Moon body centre). */
  center: string;
  /** Reference frame of the stored vectors. */
  frame: string;
  /** ISO instant of knot 0 (UTC). */
  startIso: string;
  /** Uniform knot spacing [s]. */
  stepSec: number;
  /** Number of knots per body. */
  count: number;
  /** Sun position from the Moon's centre [km], flat x,y,z triples. */
  sun: number[];
  /** Earth position from the Moon's centre [km], flat x,y,z triples. */
  earth: number[];
  /** Measured interpolation accuracy of this table (from the probe pass). */
  validation: {
    probeOffsetSec: number;
    probeCount: number;
    maxSunAngErrDeg: number;
    maxEarthAngErrDeg: number;
    maxSunDistErrKm: number;
    maxEarthDistErrKm: number;
    probeSamples: HorizonsProbeSample[];
  };
}

import { HORIZONS_BAKED } from "./horizonsBakedData";

/** The baked table itself (generated — see tools/prep_ephemeris.py). */
export { HORIZONS_BAKED };

const G = HORIZONS_BAKED;

/** Knot 0 [ms since epoch]. */
export const bakedStartMs = Date.parse(G.startIso);
/** Last knot [ms since epoch]. */
export const bakedEndMs = bakedStartMs + (G.count - 1) * G.stepSec * 1000;

/** True when `epochMs` falls inside the baked window (both endpoints inclusive). */
export function bakedCovers(epochMs: number): boolean {
  return epochMs >= bakedStartMs && epochMs <= bakedEndMs;
}

function catmull(p0: number, p1: number, p2: number, p3: number, u: number): number {
  return (
    0.5 *
    (2 * p1 +
      (-p0 + p2) * u +
      (2 * p0 - 5 * p1 + 4 * p2 - p3) * u * u +
      (-p0 + 3 * p1 - 3 * p2 + p3) * u * u * u)
  );
}

/**
 * Catmull-Rom on the uniform knot grid. `f` is the fractional knot index.
 * MUST mirror `interp_at()` in tools/prep_ephemeris.py (the tests cross-check
 * both against the embedded probe samples).
 */
function interpTriple(flat: readonly number[], f: number): Vec3 {
  const n = Math.floor(flat.length / 3);
  let i = Math.floor(f);
  if (i < 0) i = 0;
  if (i > n - 2) i = n - 2;
  const u = f - i;
  const comp = (c: 0 | 1 | 2): number => {
    const at = (k: number): number => {
      const kk = Math.min(Math.max(k, 0), n - 1);
      return flat[3 * kk + c]!;
    };
    let p0 = at(i - 1);
    let p1 = at(i);
    let p2 = at(i + 1);
    let p3 = at(i + 2);
    if (i === 0) p0 = 3 * at(0) - 3 * at(1) + at(2);
    if (i === n - 2 && n >= 3) p3 = 3 * at(n - 1) - 3 * at(n - 2) + at(n - 3);
    return catmull(p0, p1, p2, p3, u);
  };
  return { x: comp(0), y: comp(1), z: comp(2) };
}

/**
 * Interpolated Sun/Earth position from the Moon's centre [km], ICRF.
 * Null outside the baked window.
 */
export function bakedIcrf(epochMs: number): { sun: Vec3; earth: Vec3 } | null {
  const f = (epochMs - bakedStartMs) / (G.stepSec * 1000);
  if (!(f >= 0 && f <= G.count - 1)) return null;
  return { sun: interpTriple(G.sun, f), earth: interpTriple(G.earth, f) };
}

/**
 * Sun/Earth state from the baked JPL vectors, in the same `SkyState` shape the
 * analytic engine returns (ME frame via the shared IAU lunar orientation
 * model). Null outside the baked window.
 */
export function bakedSkyState(epochMs: number): SkyState | null {
  const v = bakedIcrf(epochMs);
  if (!v) return null;
  const toMe = eqjToMe(new Date(epochMs));
  const sunMe = toMe(v.sun);
  const earthMe = toMe(v.earth);
  const sunDistKm = Math.hypot(v.sun.x, v.sun.y, v.sun.z);
  const earthDistKm = Math.hypot(v.earth.x, v.earth.y, v.earth.z);
  const nSun = Math.hypot(sunMe.x, sunMe.y, sunMe.z) || 1;
  const nEarth = Math.hypot(earthMe.x, earthMe.y, earthMe.z) || 1;
  return {
    sunME: { x: sunMe.x / nSun, y: sunMe.y / nSun, z: sunMe.z / nSun },
    earthME: { x: earthMe.x / nEarth, y: earthMe.y / nEarth, z: earthMe.z / nEarth },
    sunDistAU: sunDistKm / AU_KM,
    earthDistKm,
    sunAngRadius: Math.asin(695_700 / sunDistKm),
    earthAngRadius: Math.asin((R_EARTH / 1000) * 1.02 / earthDistKm),
  };
}

/** Angle between two direction vectors [deg]. */
function angDeg(a: Vec3, b: Vec3): number {
  const cx = a.y * b.z - a.z * b.y;
  const cy = a.z * b.x - a.x * b.z;
  const cz = a.x * b.y - a.y * b.x;
  return Math.atan2(Math.hypot(cx, cy, cz), a.x * b.x + a.y * b.y + a.z * b.z) * RAD2DEG;
}

export interface EphemerisAgreement {
  /** Epochs compared (inside the baked window). */
  samples: number;
  maxSunAngErrDeg: number;
  maxEarthAngErrDeg: number;
  maxEarthDistErrKm: number;
  /** The single number the validation row shows: worst direction deviation. */
  maxAngErrDeg: number;
}

/**
 * Model-vs-JPL agreement sweep: how far the analytic engine (astronomy-engine
 * + IAU rotation) drifts from the pre-baked JPL HORIZONS vectors over a window.
 * Both sides share the ME rotation, so this measures the state-vector
 * difference only — the claim "the ephemeris is validated against JPL"
 * quantified, not asserted.
 */
export function ephemerisAgreement(t0Ms: number, t1Ms: number, stepMs: number): EphemerisAgreement {
  const step = Math.max(60_000, stepMs);
  let maxSun = 0;
  let maxEarth = 0;
  let maxDist = 0;
  let samples = 0;
  for (let t = t0Ms; t <= t1Ms; t += step) {
    const baked = bakedSkyState(t);
    if (!baked) continue;
    const model = skyState(new Date(t));
    const s = angDeg(model.sunME, baked.sunME);
    const e = angDeg(model.earthME, baked.earthME);
    if (s > maxSun) maxSun = s;
    if (e > maxEarth) maxEarth = e;
    const d = Math.abs(model.earthDistKm - baked.earthDistKm);
    if (d > maxDist) maxDist = d;
    samples++;
  }
  return {
    samples,
    maxSunAngErrDeg: maxSun,
    maxEarthAngErrDeg: maxEarth,
    maxEarthDistErrKm: maxDist,
    maxAngErrDeg: Math.max(maxSun, maxEarth),
  };
}
